const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;
const n = data[pos++];

const key = new Float64Array(n + 1);
const priority = new Uint32Array(n + 1);
const left = new Int32Array(n + 1);
const right = new Int32Array(n + 1);
const size = new Int32Array(n + 1);
const count = new Int32Array(n + 1);

let nodes = 0;
let seed = 0x9e3779b9;

function randomUint() {
  seed ^= seed << 13;
  seed ^= seed >>> 17;
  seed ^= seed << 5;
  return seed >>> 0;
}

function nodeSize(v) {
  return v === 0 ? 0 : size[v];
}

function update(v) {
  size[v] = size[left[v]] + size[right[v]] + count[v];
}

function rotateRight(v) {
  const u = left[v];
  left[v] = right[u];
  right[u] = v;
  update(v);
  update(u);
  return u;
}

function rotateLeft(v) {
  const u = right[v];
  right[v] = left[u];
  left[u] = v;
  update(v);
  update(u);
  return u;
}

function insert(v, k) {
  if (v === 0) {
    const u = ++nodes;
    key[u] = k;
    priority[u] = randomUint();
    size[u] = count[u] = 1;
    return u;
  }

  if (k === key[v]) {
    count[v]++;
  } else if (k < key[v]) {
    left[v] = insert(left[v], k);
    if (priority[left[v]] < priority[v]) v = rotateRight(v);
  } else {
    right[v] = insert(right[v], k);
    if (priority[right[v]] < priority[v]) v = rotateLeft(v);
  }

  update(v);
  return v;
}

function countAtMost(v, k) {
  let result = 0;
  while (v !== 0) {
    if (key[v] <= k) {
      result += nodeSize(left[v]) + count[v];
      v = right[v];
    } else {
      v = left[v];
    }
  }
  return result;
}

let root = 0;
let previousPenalty = 0;
const output = [];

for (let i = 0; i < n; i++) {
  const x = data[pos++] + previousPenalty;
  const y = data[pos++] + previousPenalty;
  const distanceSquared = x * x + y * y;

  const penalty = countAtMost(root, distanceSquared);
  output.push(String(penalty));
  root = insert(root, distanceSquared);
  previousPenalty = penalty;
}

console.log(output.join('\n'));
